1	//! Requirement installation during workflow execution.
2	//!
3	//! Handles interactive remediation of requirement gaps found during
4	//! a workflow run: PATH activation for inactive tools, starting
5	//! services, and offering to install missing requirements.
6	
7	use crate::error::{BivvyError, Result};
8	use crate::requirements::checker::GapChecker;
9	use crate::requirements::status::{GapResult, RequirementStatus};
10	use crate::ui::{OutputWriter, Prompt, PromptType, UserInterface};
11	use std::path::Path;
12	use std::sync::{Arc, Mutex};
13	
14	/// Mockable dependencies for the installer.
15	pub struct InstallerContext<'a> {
16	    /// Run a shell command, returning true on success.
17	    pub run_command: &'a dyn Fn(&str) -> bool,
18	    /// Check whether the network is reachable.
19	    pub check_network: &'a dyn Fn() -> bool,
20	    /// Prepend a directory to the process PATH.
21	    pub prepend_path: &'a dyn Fn(&Path),
22	}
23	
24	/// Handle all requirement gaps for a step.
25	///
26	/// Returns `Ok(true)` if the step can proceed, `Ok(false)` if
27	/// it should be skipped, or `Err` with `RequirementMissing`.
28	pub fn handle_gaps(
29	    gaps: &[GapResult],
30	    checker: &mut GapChecker<'_>,
31	    ui: &mut dyn UserInterface,
32	    interactive: bool,
33	    ctx: &InstallerContext<'_>,
34	) -> Result<bool> {
35	    if gaps.is_empty() {
36	        return Ok(true);
37	    }
38	
39	    let mut blocking = Vec::new();
40	
41	    for gap in gaps {
42	        let outcome = if interactive {
43	            handle_gap_interactive(gap, checker, ui, ctx)
44	        } else {
45	            handle_gap_non_interactive(gap, ui)
46	        };
47	
48	        match outcome {
49	            Outcome::Resolved | Outcome::CanProceed => {}
50	            Outcome::Skip { reason } => {
51	                ui.warning(&reason);
52	                return Ok(false);
53	            }
54	            Outcome::Blocked { requirement } => {
55	                blocking.push(requirement);
56	            }
57	        }
58	    }
59	
60	    if blocking.is_empty() {
61	        Ok(true)
62	    } else {
63	        let names: Vec<&str> = blocking.iter().map(|s| s.as_str()).collect();
64	        Err(BivvyError::RequirementMissing {
65	            requirement: names.join(", "),
66	            message: format!(
67	                "Missing requirements: {}. Run 'bivvy lint' for details.",
68	                names.join(", ")
69	            ),
70	        })
71	    }
72	}
73	
74	/// Accumulated PATH additions, shared between `prepend_path` and `run_command`
75	/// in the default installer context. Avoids mutating the global process
76	/// environment with `set_var`.
77	type PathAdditions = Arc<Mutex<Vec<std::path::PathBuf>>>;
78	
79	/// Build the default `InstallerContext` for production use.
80	///
81	/// PATH modifications are accumulated in a shared list rather than mutating
82	/// the global process environment. The `run_command` closure prepends these
83	/// additions to the inherited PATH when spawning child processes.
84	pub fn default_context() -> InstallerContext<'static> {
85	    // Leaked so the closures can have 'static lifetime (matches previous API).
86	    // Only one InstallerContext is created per workflow run, so the leak is bounded.
87	    let additions: &'static PathAdditions = Box::leak(Box::new(Arc::new(Mutex::new(Vec::new()))));
88	
89	    let run_additions = additions.clone();
90	    let prepend_additions = additions.clone();
91	
92	    InstallerContext {
93	        run_command: Box::leak(Box::new(move |cmd: &str| {
94	            let mut command = std::process::Command::new("sh");
95	            command.arg("-c").arg(cmd);
96	
97	            // Build PATH with accumulated additions prepended
98	            let extras = run_additions.lock().unwrap();
99	            if !extras.is_empty() {
100	                let current = std::env::var("PATH").unwrap_or_default();
101	                let prefix = extras
102	                    .iter()
103	                    .map(|p| p.to_string_lossy().to_string())
104	                    .collect::<Vec<_>>()
105	                    .join(":");
106	                let new_path = format!("{}:{}", prefix, current);
107	                command.env("PATH", new_path);
108	            }
109	
110	            command.status().is_ok_and(|s| s.success())
111	        })),
112	        check_network: &|| {
113	            use std::net::TcpStream;
114	            use std::time::Duration;
115	            let timeout = Duration::from_secs(2);
116	            let addr: std::net::SocketAddr = "1.1.1.1:443".parse().unwrap();
117	            TcpStream::connect_timeout(&addr, timeout).is_ok()
118	        },
119	        prepend_path: Box::leak(Box::new(move |dir: &Path| {
120	            let mut extras = prepend_additions.lock().unwrap();
121	            let path = dir.to_path_buf();
122	            if !extras.contains(&path) {
123	                extras.push(path);
124	            }
125	        })),
126	    }
127	}
128	
129	#[derive(Debug, PartialEq)]
130	enum Outcome {
131	    Resolved,
132	    CanProceed,
133	    Skip { reason: String },
134	    Blocked { requirement: String },
135	}
136	
137	fn handle_gap_interactive(
138	    gap: &GapResult,
139	    checker: &mut GapChecker<'_>,
140	    ui: &mut dyn UserInterface,
141	    ctx: &InstallerContext<'_>,
142	) -> Outcome {
143	    match &gap.status {
144	        RequirementStatus::Satisfied => Outcome::Resolved,
145	        RequirementStatus::Inactive {
146	            binary_path,
147	            activation_hint,
148	            ..
149	        } => handle_inactive(&gap.requirement, binary_path, activation_hint, checker, ctx),
150	        RequirementStatus::ServiceDown {
151	            start_command,
152	            start_hint,
153	            ..
154	        } => handle_service_down(
155	            &gap.requirement,
156	            start_command.as_deref(),
157	            start_hint,
158	            checker,
159	            ui,
160	            ctx,
161	        ),
162	        RequirementStatus::Missing {
163	            install_template,
164	            install_hint,
165	        } => handle_missing(
166	            &gap.requirement,
167	            install_template.as_deref(),
168	            install_hint.as_deref(),
169	            checker,
170	            ui,
171	            ctx,
172	        ),
173	        RequirementStatus::SystemOnly {
174	            warning,
175	            install_template,
176	            ..
177	        } => handle_system_only(
178	            &gap.requirement,
179	            warning,
180	            install_template.as_deref(),
181	            checker,
182	            ui,
183	            ctx,
184	        ),
185	        RequirementStatus::Unknown => Outcome::Blocked {
186	            requirement: gap.requirement.clone(),
187	        },
188	    }
189	}
190	
191	fn handle_gap_non_interactive(gap: &GapResult, ui: &mut dyn OutputWriter) -> Outcome {
192	    match &gap.status {
193	        RequirementStatus::Satisfied => Outcome::Resolved,
194	        RequirementStatus::SystemOnly { warning, .. } => {
195	            ui.warning(warning);
196	            Outcome::CanProceed
197	        }
198	        RequirementStatus::Inactive {
199	            manager,
200	            activation_hint,
201	            ..
202	        } => {
203	            ui.warning(&format!(
204	                "'{}' found via {} but not activated. {}",
205	                gap.requirement, manager, activation_hint
206	            ));
207	            Outcome::Blocked {
208	                requirement: gap.requirement.clone(),
209	            }
210	        }
211	        RequirementStatus::ServiceDown { .. }
212	        | RequirementStatus::Missing { .. }
213	        | RequirementStatus::Unknown => Outcome::Blocked {
214	            requirement: gap.requirement.clone(),
215	        },
216	    }
217	}
218	
219	// 6A: Inactive — PATH activation
220	fn handle_inactive(
221	    requirement: &str,
222	    binary_path: &Path,
223	    activation_hint: &str,
224	    checker: &mut GapChecker<'_>,
225	    ctx: &InstallerContext<'_>,
226	) -> Outcome {
227	    if let Some(parent) = binary_path.parent() {
228	        (ctx.prepend_path)(parent);
229	        checker.invalidate(requirement);
230	        Outcome::Resolved
231	    } else {
232	        Outcome::Skip {
233	            reason: format!("'{}' activation failed. {}", requirement, activation_hint),
234	        }
235	    }
236	}
237	
238	// 6B: ServiceDown — offer to start
239	fn handle_service_down(
240	    requirement: &str,
241	    start_command: Option<&str>,
242	    start_hint: &str,
243	    checker: &mut GapChecker<'_>,
244	    ui: &mut dyn UserInterface,
245	    ctx: &InstallerContext<'_>,
246	) -> Outcome {
247	    let Some(cmd) = start_command else {
248	        return Outcome::Skip {
249	            reason: format!("Service '{}' is not running. {}", requirement, start_hint),
250	        };
251	    };
252	
253	    let prompt = Prompt {
254	        key: format!("start_{}", requirement),
255	        question: format!("Start {}? ({})", requirement, cmd),
256	        prompt_type: PromptType::Confirm,
257	        default: Some("yes".to_string()),
258	    };
259	
260	    let confirmed = ui
261	        .prompt(&prompt)
262	        .ok()
263	        .and_then(|r| r.as_bool())
264	        .unwrap_or(false);
265	
266	    if !confirmed {
267	        return Outcome::Skip {
268	            reason: format!("Service '{}' is not running. {}", requirement, start_hint),
269	        };
270	    }
271	
272	    if (ctx.run_command)(cmd) {
273	        checker.invalidate(requirement);
274	        Outcome::Resolved
275	    } else {
276	        Outcome::Skip {
277	            reason: format!("Failed to start '{}'. {}", requirement, start_hint),
278	        }
279	    }
280	}
281	
282	// 6C: Missing — install offer
283	fn handle_missing(
284	    requirement: &str,
285	    install_template: Option<&str>,
286	    install_hint: Option<&str>,
287	    checker: &mut GapChecker<'_>,
288	    ui: &mut dyn UserInterface,
289	    ctx: &InstallerContext<'_>,
290	) -> Outcome {
291	    let hint = install_hint.unwrap_or("Install manually");
292	
293	    if install_template.is_none() {
294	        return Outcome::Skip {
295	            reason: format!("Missing requirement '{}'. {}", requirement, hint),
296	        };
297	    }
298	
299	    if !(ctx.check_network)() {
300	        return Outcome::Skip {
301	            reason: format!(
302	                "Installation of '{}' requires network access, which isn't available.",
303	                requirement
304	            ),
305	        };
306	    }
307	
308	    match checker.resolve_install_deps(requirement) {
309	        Ok(deps) => {
310	            for dep in &deps {
311	                if dep == requirement {
312	                    continue;
313	                }
314	                let dep_status = checker.check_one(dep);
315	                if dep_status.is_satisfied() || dep_status.can_proceed() {
316	                    continue;
317	                }
318	                let dep_prompt = Prompt {
319	                    key: format!("install_{}", dep),
320	                    question: format!("Install dependency '{}'?", dep),
321	                    prompt_type: PromptType::Confirm,
322	                    default: Some("yes".to_string()),
323	                };
324	                let confirmed = ui
325	                    .prompt(&dep_prompt)
326	                    .ok()
327	                    .and_then(|r| r.as_bool())
328	                    .unwrap_or(false);
329	                if !confirmed {
330	                    return Outcome::Skip {
331	                        reason: format!(
332	                            "Dependency '{}' for '{}' not installed.",
333	                            dep, requirement
334	                        ),
335	                    };
336	                }
337	                checker.invalidate(dep);
338	            }
339	        }
340	        Err(e) => {
341	            ui.warning(&format!(
342	                "Could not resolve dependencies for '{}': {}",
343	                requirement, e
344	            ));
345	        }
346	    }
347	
348	    let prompt = Prompt {
349	        key: format!("install_{}", requirement),
350	        question: format!("Install {}?", requirement),
351	        prompt_type: PromptType::Confirm,
352	        default: Some("yes".to_string()),
353	    };
354	
355	    let confirmed = ui
356	        .prompt(&prompt)
357	        .ok()
358	        .and_then(|r| r.as_bool())
359	        .unwrap_or(false);
360	
361	    if !confirmed {
362	        return Outcome::Skip {
363	            reason: format!("Missing requirement '{}'. {}", requirement, hint),
364	        };
365	    }
366	
367	    let install_success = if let Some(hint_cmd) = install_hint {
368	        (ctx.run_command)(hint_cmd)
369	    } else {
370	        false
371	    };
372	
373	    if !install_success {
374	        return Outcome::Skip {
375	            reason: format!(
376	                "Installation of '{}' failed. Check output above.",
377	                requirement
378	            ),
379	        };
380	    }
381	
382	    // Install exited 0 — invalidate cache and verify the tool is now on PATH
383	    checker.invalidate(requirement);
384	    let status = checker.check_one(requirement);
385	
386	    if status.is_satisfied() {
387	        Outcome::Resolved
388	    } else {
389	        Outcome::Skip {
390	            reason: format!(
391	                "Installed '{}' (exit 0) but not found on PATH. May need shell restart.",
392	                requirement
393	            ),
394	        }
395	    }
396	}
397	
398	// 6D: SystemOnly — warn + optional managed install
399	fn handle_system_only(
400	    requirement: &str,
401	    warning: &str,
402	    install_template: Option<&str>,
403	    checker: &mut GapChecker<'_>,
404	    ui: &mut dyn UserInterface,
405	    ctx: &InstallerContext<'_>,
406	) -> Outcome {
407	    ui.warning(warning);
408	
409	    if install_template.is_none() {
410	        return Outcome::CanProceed;
411	    }
412	
413	    let prompt = Prompt {
414	        key: format!("managed_install_{}", requirement),
415	        question: format!("Install a managed version of {}?", requirement),
416	        prompt_type: PromptType::Confirm,
417	        default: Some("no".to_string()),
418	    };
419	
420	    let confirmed = ui
421	        .prompt(&prompt)
422	        .ok()
423	        .and_then(|r| r.as_bool())
424	        .unwrap_or(false);
425	
426	    if !confirmed {
427	        return Outcome::CanProceed;
428	    }
429	
430	    let result = handle_missing(requirement, install_template, None, checker, ui, ctx);
431	    match result {
432	        Outcome::Resolved => Outcome::Resolved,
433	        _ => Outcome::CanProceed,
434	    }
435	}
