515	    // --- 6B: ServiceDown tests ---
516	
517	    #[test]
518	    fn service_down_offers_to_start() {
519	        let registry = RequirementRegistry::new();
520	        let probe = make_probe();
521	        let temp = TempDir::new().unwrap();
