983	    #[test]
984	    fn missing_install_success_but_not_on_path() {
985	        // Scenario: A requirement is Missing, the user confirms install,
986	        // the install command exits 0 (success), but after invalidating
987	        // cache and re-checking, the tool is STILL not found on PATH.
988	        // Expected: Outcome::Skip with message containing "may need shell restart".
989	        //
990	        // We use a custom requirement registered via with_custom whose check
991	        // command always fails ("false"), so after install + re-check the
992	        // tool remains missing.
993	        use crate::config::{CustomRequirement, CustomRequirementCheck};
994	        use std::collections::HashMap;
995	
996	        let mut custom = HashMap::new();
997	        custom.insert(
998	            "phantom-tool".to_string(),
999	            CustomRequirement {
1000	                check: CustomRequirementCheck::CommandSucceeds {
1001	                    command: "false".to_string(),
1002	                },
1003	                install_template: Some("phantom-install".to_string()),
1004	                install_hint: Some("install-phantom-tool".to_string()),
1005	            },
1006	        );
1007	
1008	        let registry = RequirementRegistry::new().with_custom(&custom);
1009	        let probe = make_probe();
1010	        let temp = TempDir::new().unwrap();
1011	        let mut checker = make_checker(&registry, &probe, &temp);
1012	        let mut ui = MockUI::new();
1013	        ui.set_interactive(true);
1014	        ui.set_prompt_response("install_phantom-tool", "yes");
1015	
1016	        // run_command returns true (install "succeeds" exit 0),
1017	        // but network is available and the check still fails after install
1018	        let ctx = stub_ctx(true, true);
1019	
1020	        let gaps = vec![GapResult {
1021	            requirement: "phantom-tool".to_string(),
1022	            status: RequirementStatus::Missing {
1023	                install_template: Some("phantom-install".to_string()),
1024	                install_hint: Some("install-phantom-tool".to_string()),
1025	            },
1026	        }];
1027	
1028	        let result = handle_gaps(&gaps, &mut checker, &mut ui, true, &ctx);
1029	        // Should skip (not error) because install exited 0 but tool not found
1030	        assert!(!result.unwrap(), "should return false (skip)");
1031	        assert!(
1032	            ui.has_warning("not found on PATH")
1033	                || ui.has_warning("may need shell restart")
1034	                || ui.has_warning("May need shell restart"),
1035	            "should warn about PATH or shell restart, warnings: {:?}",
1036	            ui.warnings()
1037	        );
1038	    }
