        assert_ne!(path1, path2);
    }

    #[test]
    fn concurrent_stores_produce_consistent_state() {
        use std::sync::{Arc, Barrier};
        use std::thread;

        let temp = TempDir::new().unwrap();
        let store = Arc::new(CacheStore::new(temp.path()));
        let num_writers = 10;
        let barrier = Arc::new(Barrier::new(num_writers));

        let mut handles = Vec::new();
        for i in 0..num_writers {
            let store = Arc::clone(&store);
            let barrier = Arc::clone(&barrier);
            let content = format!("content-from-thread-{}", i);
            handles.push(thread::spawn(move || {
                barrier.wait();
                store
                    .store("http:test", "shared-template", &content, 3600)
                    .unwrap();
            }));
        }

        for h in handles {
            h.join().unwrap();
        }

        let entry = store.load("http:test", "shared-template").unwrap().unwrap();
        let content = store.read_content(&entry).unwrap();

        assert!(
            content.starts_with("content-from-thread-"),
            "content should be a complete write from one thread, got: {:?}",
            content
        );
        assert_eq!(entry.metadata.size_bytes, content.len() as u64);
    }

    #[test]
    fn concurrent_reads_never_see_partial_content() {
        use std::sync::{Arc, Barrier};
        use std::thread;
        use std::time::Duration;

        let temp = TempDir::new().unwrap();
        let store = Arc::new(CacheStore::new(temp.path()));

        store
            .store("http:test", "template", "initial-content", 3600)
            .unwrap();

        let num_writers = 5;
        let num_readers = 5;
        let barrier = Arc::new(Barrier::new(num_writers + num_readers));

        let mut handles = Vec::new();

        for i in 0..num_writers {
            let store = Arc::clone(&store);
            let barrier = Arc::clone(&barrier);
            handles.push(thread::spawn(move || {
                barrier.wait();
                for j in 0..20 {
                    let content = format!("writer-{}-iteration-{}", i, j);
                    store.store("http:test", "template", &content, 3600).unwrap();
                }
            }));
        }

        for _ in 0..num_readers {
            let store = Arc::clone(&store);
            let barrier = Arc::clone(&barrier);
            handles.push(thread::spawn(move || {
                barrier.wait();
                for _ in 0..100 {
                    if let Ok(Some(entry)) = store.load("http:test", "template") {
                        if let Ok(content) = store.read_content(&entry) {
                            assert!(
                                !content.is_empty(),
                                "reader saw empty content (truncated file)"
                            );
                            assert_eq!(
                                entry.metadata.size_bytes,
                                content.len() as u64,
                                "metadata size {} doesn't match content len {}",
                                entry.metadata.size_bytes,
                                content.len()
                            );
                        }
                    }
                    thread::sleep(Duration::from_micros(50));
                }
            }));
        }

        for h in handles {
            h.join().unwrap();
        }
    }

    #[test]
    fn concurrent_stores_to_different_entries_all_succeed() {
        use std::sync::Arc;
        use std::thread;

        let temp = TempDir::new().unwrap();
        let store = Arc::new(CacheStore::new(temp.path()));

        let mut handles = Vec::new();
        for i in 0..10 {
            let store = Arc::clone(&store);
            handles.push(thread::spawn(move || {
                let name = format!("template-{}", i);
                let content = format!("content-{}", i);
                store.store("http:test", &name, &content, 3600).unwrap();
            }));
        }

        for h in handles {
            h.join().unwrap();
        }

        let entries = store.list().unwrap();
        assert_eq!(entries.len(), 10);

        for i in 0..10 {
            let name = format!("template-{}", i);
            let expected = format!("content-{}", i);
            let entry = store.load("http:test", &name).unwrap().unwrap();
            let content = store.read_content(&entry).unwrap();
            assert_eq!(content, expected);
            assert_eq!(entry.metadata.size_bytes, expected.len() as u64);
        }
    }

    #[test]
    fn no_temp_files_left_after_store() {
        let temp = TempDir::new().unwrap();
        let store = CacheStore::new(temp.path());

        store
            .store("http:test", "template1", "content", 3600)
            .unwrap();

        let dir_entries: Vec<_> = fs::read_dir(temp.path())
            .unwrap()
            .filter_map(|e| e.ok())
            .collect();

        for entry in &dir_entries {
            let name = entry.file_name();
            let name_str = name.to_string_lossy();
            assert!(
                !name_str.contains(".tmp"),
                "temporary file should not remain: {:?}",
                name_str
            );
        }
    }

    #[test]
    fn store_is_atomic_metadata_matches_content() {
        let temp = TempDir::new().unwrap();
        let store = CacheStore::new(temp.path());

        let content = "x".repeat(4096);
        store
            .store("http:test", "big-template", &content, 3600)
            .unwrap();

        let entry = store.load("http:test", "big-template").unwrap().unwrap();
        let read_back = store.read_content(&entry).unwrap();
        assert_eq!(read_back, content);
        assert_eq!(entry.metadata.size_bytes, content.len() as u64);
    }
}

