/// Load a cached entry's metadata.
///
/// Returns `None` if the entry does not exist or if the metadata is
/// inconsistent with the content on disk (which can happen transiently
/// during concurrent writes).
pub fn load(&self, source_id: &str, template_name: &str) -> Result<Option<CacheEntry>> {
    let meta_path = self.metadata_path(source_id, template_name);

    if !meta_path.exists() {
        return Ok(None);
    }

    let json = match fs::read_to_string(&meta_path) {
        Ok(j) => j,
        Err(_) => return Ok(None),
    };

    let entry: CacheEntry = match serde_json::from_str(&json) {
        Ok(e) => e,
        Err(_) => return Ok(None),
    };

    let content_meta = match fs::metadata(&entry.content_path) {
        Ok(m) => m,
        Err(_) => return Ok(None),
    };

    if content_meta.len() != entry.metadata.size_bytes {
        return Ok(None);
    }

    Ok(Some(entry))
}

