        let store = Arc::new(CacheStore::new(temp.path()));

        store
            .store("http:test", "template", "initial-content", 3600)
            .unwrap();

        let num_writers = 5;
        let num_readers = 5;
        let barrier = Arc::new(Barrier::new(num_writers + num_readers));

        let mut handles = Vec::new();

        for i in 0..num_writers {
            let store = Arc::clone(&store);
            let barrier = Arc::clone(&barrier);
            handles.push(thread::spawn(move || {
                barrier.wait();
                for j in 0..20 {
                    let content = format!("writer-{}-iteration-{}", i, j);
                    store.store("http:test", "template", &content, 3600).unwrap();
                }
            }));
        }

        for _ in 0..num_readers {
            let store = Arc::clone(&store);
            let barrier = Arc::clone(&barrier);
            handles.push(thread::spawn(move || {
                barrier.wait();
                for _ in 0..100 {
                    if let Ok(Some(entry)) = store.load("http:test", "template") {
                        if let Ok(content) = store.read_content(&entry) {
                            assert!(
                                !content.is_empty(),
                                "reader saw empty content (truncated file)"
                            );
                            assert_eq!(
                                entry.metadata.size_bytes,
                                content.len() as u64,
                                "metadata size {} doesn't match content len {}",
                                entry.metadata.size_bytes,
                                content.len()
                            );
                        }
                    }
                    thread::sleep(Duration::from_micros(50));
                }
            }));
        }

        for h in handles {
            h.join().unwrap();
        }
    }

    #[test]
    fn concurrent_stores_to_different_entries_all_succeed() {
        use std::sync::Arc;
        use std::thread;

        let temp = TempDir::new().unwrap();
        let store = Arc::new(CacheStore::new(temp.path()));

        let mut handles = Vec::new();
