//! Cache storage implementation.

use anyhow::{Context, Result};
use sha2::{Digest, Sha256};
use std::fs;
use std::path::{Path, PathBuf};

use super::entry::CacheEntry;

/// Write data to a temporary file in the same directory, then atomically
/// rename it to the final path. This prevents readers from ever observing
/// a partially-written or truncated file.
fn atomic_write(path: &Path, data: &[u8]) -> Result<()> {
    let dir = path
        .parent()
        .with_context(|| format!("cache path has no parent: {:?}", path))?;

    let mut rand_buf = [0u8; 8];
    crate::sys::random_bytes(&mut rand_buf);
    let suffix = hex::encode(rand_buf);

    let tmp_path = dir.join(format!(".tmp.{}", suffix));

    fs::write(&tmp_path, data)
        .with_context(|| format!("failed to write temp file {:?}", tmp_path))?;

    fs::rename(&tmp_path, path).with_context(|| {
        let _ = fs::remove_file(&tmp_path);
        format!("failed to rename {:?} -> {:?}", tmp_path, path)
    })?;

    Ok(())
}

