+/// Write data to a temporary file in the same directory, then atomically
+/// rename it to the final path. This prevents readers from ever observing
+/// a partially-written or truncated file.
+fn atomic_write(path: &Path, data: &[u8]) -> Result<()> {
+    let dir = path
+        .parent()
